        requirements = "Garrison invasion access; use a level 3 Garrison for the complete farm",
        commentIds = { 2575863, 2144817, 5846683 },
        tips = "Gold requires 1,000 points and Platinum 1,300. Repeating invasions does not repeatedly award the weekly bags. Do not assume guards alone will reach Platinum; their scaling has changed across patches.",
        waypoints = {
            {
