    [171627] = {
        category = "Achievements",
        source = "Guild vendor after Guild Glory of the Draenor Raider",
        description = "An obtainable personal vendor purchase after joining a guild with the mount unlock.",
        difficulty = "medium",
        difficultyReason = "Find an unlocked guild, earn guild Exalted and pay the vendor price.",
