        cost = "4,000 gold at the guild vendor",
        commentIds = { 2128472, 5988570, 6355861 },
        tips = "This is a mount purchase, so it remains in the mount catalogue. The guild achievement itself need not be included in the personal achievement catalogue. A guild does not need to repeat its already-completed unlock for a new member.",
