        mountCategory = "Vendor",
        sourceType = "Vendor",
        tips = "",
        stepCount = 3,
        acquisition = "Difficulty: Medium - Accumulate the gold and Apexis Crystals, then make the guaranteed vendor purchase.\n\n1. Check your Currency tab for Apexis Crystals. Earn any shortfall from Garrison Scouting Missives, Tanaan daily quests and bonus objectives; do not confuse the currency with Apexis Shards from Outland.\n\n2. Go to Dawn-Seeker Krek in Stormshield (51.2,61.8) on Alliance, or Dawn-Seeker Alkset in Warspear (65.2,64.2) on Horde. They are the Draenor Apexis vendors.\n\n3. Buy Mosshide Riverwallow for 5,000 Apexis Crystals plus the vendor's 50,000 gold base price, then learn the item. No Exalted reputation unlock is required for this mount.",
    },
    [171828] = {
        category = "Rare Drops",
        source = "Rukhmar, Spires of Arak",
        npcId = 83746,
        description = "A rare personal-loot reward from the outdoor world boss Rukhmar.",
        difficulty = "hard",
        difficultyReason = "A contested world-boss spawn and a weekly character-specific random reward.",
        commentIds = { 2097595, 5181265, 5771647 },
        tips = "Solar Spirehawk cannot be bonus rolled. Repeated same-character kills in one week do not provide more mount rolls. Temporary Collector's Bounty event rates are not a permanent drop rate.",
        waypoints = { { mapID = 542, x = 0.37, y = 0.39, step = 1, label = "Rukhmar coastal spawn / patrol search area" } },
        reviewedAt = "2026-11-14",
        itemId = 116771,
        name = "Solar Spirehawk",
        wowheadUrl = "https://www.wowhead.com/item=116771",
        mountCategory = "Rare Drops",
        sourceType = "Rare Drops",
        stepCount = 5,
        acquisition = "Difficulty: Hard - A contested world-boss spawn and a weekly character-specific random reward.\n\n1. Travel to the southwest coast of Spires of Arak and wait near Rukhmar's spawn/patrol at 37.0,39.0. Look above the cliffs as well as at ground level; the boss flies along the coast.\n\n2. Get into range as Rukhmar descends and land an eligible attack before the boss dies. A group invitation alone does not replace your character's tag. Move away from fire and hatchlings if the fight lasts more than a few seconds.\n\n3. Defeat the boss and check your bags and loot messages. The mount can be delivered directly to bags through personal loot; do not assume an empty corpse means the kill failed.\n\n4. Do not buy bonus-roll coins for this mount: a Seal of Tempered Fate can roll other Rukhmar loot, but cannot award Solar Spirehawk. Use another eligible character or wait for the next weekly reset for another mount chance.\n\n5. Use Solar Spirehawk when awarded. If camping across alts, allow time for another spawn; a respawn does not reset the first character's weekly loot eligibility.",
    },
